----Edited later---
Nevermind, I found a way, I decided to make all movement route sounds spatial
JavaScript:
//My function to transform regular audio into spatial audio using MUSH Audio Engine
    myPlugin.playSpatialSe = function(sep,e){
        var se = {
            name: sep.name,
            pitch: sep.pitch,
            volume: 0
        }
        var data = {
            pitchVar: "Default",
            volumeVar: "Default",
            maxVolume: sep.volume,
            eventId: e._eventId,
            radius: 15,
            strength: 100,
            panType: "Origin Expand",
            panSt: 6,
            panLd: 6
        }
        AudioManager.playSpatialSe(se, data);
    }

    //Catch audio play from route commands
    Game_Character.prototype.oldProcessMoveCommand = Game_Character.prototype.processMoveCommand;
    Game_Character.prototype.processMoveCommand = function(command) {
        const gc = Game_Character;
        const params = command.parameters;
        if (command.code == gc.ROUTE_PLAY_SE) {
            myPlugin.playSpatialSe(params[0], this);
        } else {
            this.oldProcessMoveCommand(command);
        }
    }

